<?php
require_once __DIR__.'/../config/auth.php'; ensure_assessment_tables(); require_login();
$uid=user()['id']; $id=(int)($_GET['id']??0);
$s=db()->prepare('SELECT t.*,p.titulo,p.disciplina,p.descricao FROM prova_tentativas t JOIN provas p ON p.id=t.prova_id WHERE t.id=? AND t.usuario_id=?'); $s->execute([$id,$uid]); $t=$s->fetch();
if(!$t) exit('Resultado não encontrado.');
$q=db()->prepare('SELECT q.*,r.resposta FROM prova_perguntas q LEFT JOIN prova_respostas r ON r.pergunta_id=q.id AND r.tentativa_id=? WHERE q.prova_id=? ORDER BY q.id'); $q->execute([$id,$t['prova_id']]); $questions=$q->fetchAll();
$ordens=prova_garantir_ordens((int)$t['id'],$questions);
$pageTitle='Resultado da prova'; require __DIR__.'/../includes/header.php'; require __DIR__.'/../includes/dashboard-nav.php';
?><section class="panel"><h2><?=e($t['titulo'])?></h2><p class="subtext"><?=e($t['disciplina'])?></p><div class="dashboard-cards"><div class="card metric"><span>Nota</span><b><?=number_format($t['nota'],1,',','.')?>/10</b></div><div class="card metric"><span>Acertos</span><b><?=$t['acertos']?>/<?=$t['total']?></b></div><div class="card metric"><span>Status</span><b style="font-size:20px"><?=e($t['status']==='expirada'?'Expirada':'Finalizada')?></b></div></div></section><section class="panel"><h2>Correção detalhada</h2><?php foreach($questions as $i=>$q): $answer=$q['resposta']; $ordem=str_split($ordens[(int)$q['id']]); $correctIndex=array_search($q['correta'],$ordem,true); $answerIndex=$answer!==null ? array_search($answer,$ordem,true) : false; $answerLetter=$answerIndex!==false ? chr(97+$answerIndex) : ''; $correctLetter=$correctIndex!==false ? chr(97+$correctIndex) : ''; $ok=$answer===$q['correta']; $answerText=$answer ? $q['alternativa_'.$answer] : 'Não respondida'; $correctText=$q['alternativa_'.$q['correta']];?><div style="padding:15px 0;border-bottom:1px solid #eaf0f4"><b><?=$i+1?>. <?=e($q['pergunta'])?></b><p>Sua resposta: <span class="badge <?=$ok?'':'off'?>"><?=e($answerLetter?strtoupper($answerLetter):'NÃO RESPONDIDA')?></span> <?=e($answerText)?></p><p>Resposta correta: <b><?=e(strtoupper($correctLetter))?> — <?=e($correctText)?></b></p></div><?php endforeach;?><br><a class="btn" href="<?=base_url('aluno/provas.php')?>">Voltar para provas</a></section><?php require __DIR__.'/../includes/dashboard-footer.php';?>
